// Празни офис файлове, създадени с LibreOffice, за да се отварят в Collabora.

const B64: Record<string, string> = {
  docx: '',
  odt: '',
  xlsx: '',
  ods: '',
  pptx: '',
  odp: '',
};

export function blankOffice(kind: string): Uint8Array {
  const raw = atob(B64[kind] ?? "");
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
  return out;
}
